#include <cstdint>
#include <iostream>
#include <map>
#include <string>

constexpr std::uint32_t SE_PRIVILEGE_ENABLED_BY_DEFAULT{0x1}, SE_PRIVILEGE_ENABLED{0x2};

class Token
{
public:
    std::string check(const std::string& name) const { return "not present"; }
    bool enable(const std::string& name) { return false; }

    std::map<std::string, std::uint32_t> privileges{};
};

int main()
{
    Token t{};
    t.privileges["SeShutdownPrivilege"] = 0;
    std::cout << t.check("SeShutdownPrivilege") << '\n';
}
